function example() {
  const [folder, setFolder] = useState<string | null>('invoices');

  return (
    <>
      <TreeSelect
        label="Save to"
        value={folder}
        onChange={setFolder}
        clearable
        data={[
          {
            value: 'docs',
            label: 'Documents',
            children: [
              { value: 'invoices', label: 'Invoices' },
              { value: 'contracts', label: 'Contracts' },
            ],
          },
          { value: 'photos', label: 'Photos' },
        ]}
      />
      <Paragraph textSize="7">Value: {String(folder)}</Paragraph>
    </>
  );
}

function example() {
  const [regions, setRegions] = useState<string[]>(['france', 'germany']);

  return (
    <>
      <TreeSelect
        label="Regions"
        selectionMode="checkbox"
        value={regions}
        onChange={setRegions}
        searchable
        data={[
          {
            value: 'europe',
            label: 'Europe',
            children: [
              { value: 'france', label: 'France' },
              { value: 'germany', label: 'Germany' },
              { value: 'spain', label: 'Spain' },
            ],
          },
          {
            value: 'asia',
            label: 'Asia',
            children: [
              { value: 'japan', label: 'Japan' },
              { value: 'korea', label: 'Korea' },
            ],
          },
        ]}
      />
      <Paragraph textSize="7">Value: {JSON.stringify(regions)}</Paragraph>
    </>
  );
}

function example() {
  const [regions, setRegions] = useState<string[]>(['europe']);

  return (
    <>
      <TreeSelect
        label="Regions, as their topmost checked items"
        selectionMode="checkbox"
        checkedStrategy="parent"
        value={regions}
        onChange={setRegions}
        data={[
          {
            value: 'europe',
            label: 'Europe',
            children: [
              { value: 'france', label: 'France' },
              { value: 'germany', label: 'Germany' },
            ],
          },
          { value: 'oceania', label: 'Oceania' },
        ]}
      />
      <Paragraph textSize="7">Value: {JSON.stringify(regions)}</Paragraph>
    </>
  );
}

function example() {
  const [loaded, setLoaded] = useState(false);
  const [loading, setLoading] = useState(false);

  return (
    <TreeSelect
      label="Folder"
      onExpandedChange={expanded => {
        if (expanded.includes('photos') && !loaded && !loading) {
          setLoading(true);
          setTimeout(() => {
            setLoaded(true);
            setLoading(false);
          }, 1000);
        }
      }}
      data={[
        {
          value: 'photos',
          label: 'Photos',
          hasChildren: true,
          isLoading: loading,
          children: loaded
            ? [
                { value: 'summer', label: 'Summer' },
                { value: 'winter', label: 'Winter' },
              ]
            : undefined,
        },
        { value: 'docs', label: 'Documents' },
      ]}
    />
  );
}
